1	const express = require('express');
2	const router = express.Router();
3	const axios = require('axios');
4	const { User } = require('../models');
5	const { verifyToken, requireRole } = require('../middlewares/auth');
6	const { shouldWriteLog, createSecurityLog } = require('../services/securityAudit');
7	
8	// FACE_AI_URL is the BASE url of the InsightFace service; paths are appended.
9	const FACE_AI_URL = () => process.env.FACE_AI_URL || 'http://127.0.0.1:8501';
10	
11	// Base64 data-URL frames are ~1.33x the JPEG size; 8 MB of text comfortably
12	// covers the 420px-wide compressed frames the scanners send, and rejects abuse.
13	const MAX_IMAGE_CHARS = 8 * 1024 * 1024;
14	
15	// --- Access control -----------------------------------------------------------
16	// Gate Scanner / V-Patrol run under an FM session. A trusted edge device (e.g. a
17	// future Pi node posting frames itself) may authenticate with EDGE_SERVICE_TOKEN
18	// in an x-edge-token header instead of a user JWT.
19	const allowFMOrEdgeService = (req, res, next) => {
20	  const edgeToken = req.headers['x-edge-token'];
21	  if (edgeToken && process.env.EDGE_SERVICE_TOKEN && edgeToken === process.env.EDGE_SERVICE_TOKEN) {
22	    return next();
23	  }
24	  return verifyToken(req, res, () => requireRole('FM')(req, res, next));
25	};
26	
27	// POST /api/facial-recognition/access-event
28	// V-Patrol monitoring: records a server-owned SAFE access audit event for a
29	// verified (recognised + liveness-passed) active user WITHOUT touching
30	// attendance — V-Patrol must never toggle clock-in/out; that is the Gate
31	// Scanner's job via /api/attendance/scan. Deduplicated server-side.
32	router.post('/access-event', allowFMOrEdgeService, async (req, res) => {
33	  try {
34	    const { userId, cameraLocation } = req.body;
35	    if (userId == null || !Number.isInteger(Number(userId))) {
36	      return res.status(400).json({ error: 'Missing required parameter: userId' });
37	    }
38	    const location = typeof cameraLocation === 'string' && cameraLocation.trim()
39	      ? cameraLocation.trim().slice(0, 100)
40	      : 'Biometric Gantry';
41	
42	    const user = await User.findByPk(userId, {
43	      attributes: ['id', 'name', 'role', 'isActive', 'isEnrolled']
44	    });
45	    if (!user || !user.isEnrolled) {
46	      return res.status(404).json({ error: 'User not recognized in system registry.' });
47	    }
48	    if (!user.isActive) {
49	      return res.status(403).json({ error: 'Account suspended. Access event not recorded as granted.' });
50	    }
51	
52	    // Same dedup namespace as the attendance scan, so a person passing both the
53	    // gantry and the turnstile within the cooldown yields ONE safe log, not two.
54	    let logged = false;
55	    if (shouldWriteLog(`granted:${user.id}:${location}`)) {
56	      logged = await createSecurityLog({
57	        type: 'Gantry Access',
58	        desc: `Identity & liveness verified: ${user.name} (${user.role}) at ${location}.`,
59	        severity: 'safe',
60	        icon: '🔓',
61	        personnelName: user.name,
62	        matchedUserId: user.id,
63	        cameraLocation: location
64	      });
65	    }
66	
67	    // Safe fields only — never the biometric template.
68	    return res.status(200).json({
69	      status: 'SUCCESS',
70	      logged,
71	      worker: user.name,
72	      role: user.role
73	    });
74	  } catch (err) {
75	    console.error('Access-event error:', err);
76	    return res.status(500).json({ error: 'Could not record access event.' });
77	  }
78	});
79	
80	// POST /api/facial-recognition/recognize
81	// Frontend (Gate Scanner / V-Patrol) → Node → FastAPI → Node resolves the User
82	// record from PostgreSQL → safe recognition result. The DB — not the AI cache —
83	// decides name, role, account status, and the access outcome.
84	router.post('/recognize', allowFMOrEdgeService, async (req, res) => {
85	  const { image, cameraLocation } = req.body;
86	
87	  if (typeof image !== 'string' || !image.startsWith('data:image/')) {
88	    return res.status(400).json({ error: 'A base64 data-URL image is required.' });
89	  }
90	  if (image.length > MAX_IMAGE_CHARS) {
91	    return res.status(413).json({ error: 'Image payload too large.' });
92	  }
93	  const location = typeof cameraLocation === 'string' && cameraLocation.trim()
94	    ? cameraLocation.trim().slice(0, 100)
95	    : 'Main Gate';
96	
97	  let aiResult;
98	  const aiStartedAt = Date.now();
99	  try {
100	    const aiResponse = await axios.post(`${FACE_AI_URL()}/user/recognize`, { image }, {
101	      timeout: 15000,
102	      headers: { 'X-AI-Service-Key': process.env.AI_SERVICE_KEY || '' }
103	    });
104	    aiResult = aiResponse.data;
105	  } catch (err) {
106	    const isConnError = !err.response &&
107	      ['ECONNREFUSED', 'ECONNABORTED', 'ETIMEDOUT', 'ENOTFOUND'].includes(err.code);
108	    if (isConnError) {
109	      return res.status(503).json({ error: 'Facial recognition service is offline. Please try again shortly.' });
110	    }
111	    if (err.response) {
112	      const status = err.response.status === 400 ? 400 : 502;
113	      return res.status(status).json({ error: 'Facial recognition service returned an error.' });
114	    }
115	    console.error('Recognition forwarding error:', err.message);
116	    return res.status(502).json({ error: 'Facial recognition service returned an error.' });
117	  }
118	
119	  const { matchedUserId, confidence = 0, box = null, liveness_ratio = 0.5, faceDetected, inference_ms = null } = aiResult || {};
120	
121	  // Development timing telemetry — durations only, never images or templates.
122	  const timings = { nodeToAiMs: Date.now() - aiStartedAt, inferenceMs: inference_ms };
123	  if (process.env.NODE_ENV !== 'production') {
124	    console.log(`[recognize] Node→FastAPI ${timings.nodeToAiMs}ms, InsightFace inference ${inference_ms ?? '?'}ms`);
125	  }
126	
127	  // No face in frame → no recognition attempt, and no suspicious-person log.
128	  if (faceDetected === false || (!box && matchedUserId == null)) {
129	    return res.status(200).json({ user: null, box: null, liveness_ratio, timings });
130	  }
131	
132	  // Face detected but no template match → unknown person.
133	  if (matchedUserId == null) {
134	    if (shouldWriteLog(`unknown:${location}`)) {
135	      await createSecurityLog({
136	        type: 'Intrusion Alert',
137	        desc: `Unregistered person detected at ${location} (confidence ${Number(confidence).toFixed(2)}).`,
138	        severity: 'critical',
139	        icon: '🚨',
140	        personnelName: null,
141	        confidence,
142	        cameraLocation: location
143	      });
144	    }
145	    return res.status(200).json({
146	      user: { id: null, name: 'Unknown Person', role: null, status: 'DENIED', confidence },
147	      box,
148	      liveness_ratio,
149	      timings
150	    });
151	  }
152	
153	  // Authoritative record: PostgreSQL, looked up by the unique matched user ID.
154	  const user = await User.findByPk(matchedUserId, {
155	    attributes: ['id', 'name', 'role', 'isActive', 'isEnrolled']
156	  });
157	
158	  // Matched an ID the DB no longer knows (e.g. off-boarded but AI cache stale).
159	  if (!user || !user.isEnrolled) {
160	    if (shouldWriteLog(`stale:${matchedUserId}:${location}`)) {
161	      await createSecurityLog({
162	        type: 'Intrusion Alert',
163	        desc: `Recognition matched a non-enrolled or removed account (ref #${matchedUserId}) at ${location}. AI cache may need a refresh.`,
164	        severity: 'critical',
165	        icon: '🚨',
166	        personnelName: null,
167	        matchedUserId,
168	        confidence,
169	        cameraLocation: location
170	      });
171	    }
172	    return res.status(200).json({
173	      user: { id: null, name: 'Unknown Person', role: null, status: 'DENIED', confidence },
174	      box,
175	      liveness_ratio,
176	      timings
177	    });
178	  }
179	
180	  // Suspended account → deny access and audit it.
181	  if (!user.isActive) {
182	    if (shouldWriteLog(`suspended:${user.id}:${location}`)) {
183	      await createSecurityLog({
184	        type: 'Suspended Access Attempt',
185	        desc: `Suspended account attempted gate access at ${location}: ${user.name} (${user.role}, confidence ${Number(confidence).toFixed(2)}).`,
186	        severity: 'critical',
187	        icon: '⛔',
188	        personnelName: user.name,
189	        matchedUserId: user.id,
190	        role: user.role,
191	        confidence,
192	        cameraLocation: location
193	      });
194	    }
195	    return res.status(200).json({
196	      user: { id: user.id, name: user.name, role: user.role, status: 'SUSPENDED', confidence },
197	      box,
198	      liveness_ratio,
199	      timings
200	    });
201	  }
202	
203	  // Active, enrolled, recognised → safe fields only.
204	  return res.status(200).json({
205	    user: { id: user.id, name: user.name, role: user.role, status: 'AUTHORIZED', confidence },
206	    box,
207	    liveness_ratio,
208	    timings
209	  });
210	});
211	
212	module.exports = router;
