1	const express = require('express');
2	const router = express.Router();
3	const { User, Attendance, Invite, SecurityLog, Booking, sequelize } = require('../models');
4	const { Op } = require('sequelize');
5	const bcrypt = require('bcrypt');
6	const jwt = require('jsonwebtoken');
7	const yup = require('yup');
8	const axios = require('axios');
9	const crypto = require('crypto');
10	// Canonical auth middleware: verifies the JWT, then re-reads the account from
11	// PostgreSQL on EVERY request (deleted → 401, suspended → 403, tokenVersion
12	// mismatch → 401) and uses the DATABASE role as authoritative.
13	const { verifyToken, requireRole } = require('../middlewares/auth');
14	const { createRateLimiter } = require('../middlewares/rateLimit');
