18	// --- REGISTRATION (Multi-Level Security Gate) ---
19	router.post("/register", async (req, res) => {
20	    const { recaptchaToken, ...userData } = req.body;
21	    try {
22	        if (!recaptchaToken) return res.status(400).json({ errors: ["Security token missing."] });
23	
24	        // 1. reCAPTCHA Verification
25	        const params = new URLSearchParams();
26	        params.append('secret', process.env.RECAPTCHA_SECRET_KEY);
27	        params.append('response', recaptchaToken);
28	
29	        const googleResponse = await axios.post('https://www.google.com/recaptcha/api/siteverify', params, {
30	            headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
31	        });
32	
33	        if (!googleResponse.data.success || googleResponse.data.score < 0.5) {
34	            return res.status(403).json({ errors: ["Security check failed. Please try again."] });
35	        }
36	
37	        // 2. Data Validation
38	        let validationSchema = yup.object({
39	            name: yup.string().trim().required("Full name is required"),
40	            email: yup.string().trim().email("Invalid email format").required("Email is required"),
41	            password: yup.string().trim().min(8, "Password must be at least 8 characters").required(),
42	            role: yup.string().oneOf(['FM', 'Tenant', 'Staff']).required("Role is required"),
43	            tenantCode: yup.string().required("Access code is required")
44	        });
45	
46	        let validatedData = await validationSchema.validate(userData, { abortEarly: false });
47	
48	        // --- 3. THE SECURITY GATE ---
49	
50	        // BLOCK A: Prevent anyone from registering as FM publicly
51	        if (validatedData.role === 'FM') {
52	            return res.status(403).json({ errors: ["Administrative accounts cannot be created publicly."] });
53	        }
54	
55	        // BLOCK B: Tenant Registration (One-Time Invite Check)
56	        if (validatedData.role === 'Tenant') {
57	            const invite = await Invite.findOne({
58	                where: { code: validatedData.tenantCode, role: 'Tenant', isUsed: false }
59	            });
60	
61	            if (!invite) {
62	                return res.status(401).json({ errors: ["Invalid or used Invitation Code. Contact the FM office."] });
63	            }
64	
65	            // Check Expiration (e.g., 24h/48h set when invite was created)
66	            if (new Date() > invite.expiresAt) {
67	                return res.status(401).json({ errors: ["This invitation code has expired."] });
68	            }
69	
70	            // Mark invite as used so it cannot be used again
71	            await invite.update({ isUsed: true });
72	        }
73	
74	        // BLOCK C: Staff Registration (Hybrid Security Logic)
75	        if (validatedData.role === 'Staff') {
76	            const employer = await User.findOne({
77	                where: { role: 'Tenant', companyCode: validatedData.tenantCode }
78	            });
79	
80	            if (!employer) {
81	                return res.status(400).json({ errors: ["Invalid Unit Registration Code. Contact your manager."] });
82	            }
83	
84	            // Time Expiration Check (48 Hours)
85	            const fortyEightHours = 48 * 60 * 60 * 1000;
86	            const isExpired = Date.now() - new Date(employer.codeCreatedAt).getTime() > fortyEightHours;
87	
88	            if (isExpired) {
89	                return res.status(401).json({ errors: ["This unit code has expired (48h limit). Ask your manager to refresh it."] });
90	            }
91	
92	            // Usage Limit Check (Capacity)
93	            if (employer.codeCurrentUsage >= employer.codeMaxUsage) {
94	                return res.status(401).json({ errors: ["Registration capacity reached for this unit."] });
95	            }
96	
97	            // Link Staff to Tenant and increment usage
98	            validatedData.managerId = employer.id;
99	            await employer.increment('codeCurrentUsage');
100	        }
101	
102	        // 4. Hash & Save
103	        validatedData.password = await bcrypt.hash(validatedData.password, 10);
104	        let result = await User.create(validatedData);
105	
106	        res.json({ message: "Account registered successfully.", id: result.id });
107	
108	    } catch (err) {
109	        console.error("Registration Error Logic:", err);
110	        let errorMessages = [];
111	        if (err.name === 'SequelizeUniqueConstraintError') {
112	            errorMessages = ["This email is already registered in our system."];
113	        } else if (err.errors) {
114	            errorMessages = err.errors.map(e => (typeof e === 'object' ? e.message : e));
115	        } else {
116	            errorMessages = [err.message || "An unexpected system error occurred."];
117	        }
118	        res.status(400).json({ errors: errorMessages });
119	    }
120	});
