169	router.post("/login", async (req, res) => {
170	    let { email, password, recaptchaToken } = req.body;
171	
172	    try {
173	        // 1. Validate ReCAPTCHA Token with Google
174	        const recaptchaRes = await fetch(
175	            `https://www.google.com/recaptcha/api/siteverify?secret=${process.env.RECAPTCHA_SECRET_KEY}&response=${recaptchaToken}`,
176	            { method: 'POST' }
177	        );
178	        const recaptchaData = await recaptchaRes.json();
179	
180	        if (!recaptchaData.success) {
181	            return res.status(400).json({ message: "Security verification failed." });
182	        }
183	
184	        // 2. Find User (Use timing-attack protection logic)
185	        const user = await User.findOne({ where: { email } });
186	
187	        // Define a dummy hash to compare against if user doesn't exist
188	        const dummyHash = "$2b$10$abcdefghijklmnopqrstuv";
189	        const passwordToCompare = user ? user.password : dummyHash;
190	
191	        // 3. Compare password
192	        const match = await bcrypt.compare(password, passwordToCompare);
193	
194	        // If user not found OR password doesn't match
195	        if (!user || !match) {
196	            return res.status(400).json({ message: "Invalid email or password" });
197	        }
198	
199	        // 4. Check account status
200	        if (user.isActive === false) {
201	            return res.status(403).json({ message: "Access Denied: Account suspended." });
202	        }
203	
204	        // 5. Generate JWT Token. tokenVersion is stamped into the token and
205	        // re-checked on every authenticated request — bumping it (password
206	        // change/reset, suspension) instantly revokes tokens on lost devices.
207	        const token = jwt.sign(
208	            { id: user.id, email: user.email, role: user.role, tokenVersion: user.tokenVersion ?? 0 },
209	            process.env.APP_SECRET,
210	            { expiresIn: '1h' }
211	        );
212	
213	        res.json({
214	            token,
215	            user: {
216	                id: user.id,
217	                name: user.name,
218	                role: user.role,
219	                isEnrolled: user.isEnrolled
220	            }
221	        });
222	
223	    } catch (err) {
224	        console.error("Login Route Error:", err);
225	        res.status(500).json({ message: "Internal server error" });
226	    }
227	});
