289	        if (!user) return res.status(404).json({ message: "User not found." });
290	
291	        // FM may suspend/reactivate anyone; a Tenant only their OWN Staff.
292	        const isFM = req.user.role === 'FM';
293	        const isTenantManagingOwnStaff =
294	            req.user.role === 'Tenant' && user.role === 'Staff' && user.managerId === req.user.id;
295	        if (!isFM && !isTenantManagingOwnStaff) {
