328	router.delete("/:id", verifyToken, async (req, res) => {
329	    try {
330	        const staffMember = await User.findByPk(req.params.id);
331	        if (!staffMember) return res.status(404).json({ message: "Not found." });
332	
333	        if (String(staffMember.id) === String(req.user.id)) {
334	            return res.status(400).json({ message: "Self-deletion is restricted. Ask another Facilities Manager to off-board this account." });
335	        }
336	
337	        const isFacilitiesManager = req.user.role === 'FM';
338	        const isTenantDeletingOwnStaff = req.user.role === 'Tenant' && staffMember.managerId === req.user.id;
339	
340	        if (!isFacilitiesManager && !isTenantDeletingOwnStaff) {
341	            return res.status(403).json({ message: "Unauthorized action." });
342	        }
343	
344	        // Tenant off-boarding guard: never leave orphan Staff. The FM must
345	        // remove or reassign the tenant's Staff before the tenant account
346	        // itself can be deleted (safest PoC behaviour → 409 Conflict).
347	        if (staffMember.role === 'Tenant') {
348	            const linkedStaff = await User.count({ where: { role: 'Staff', managerId: staffMember.id } });
349	            if (linkedStaff > 0) {
350	                return res.status(409).json({
351	                    message: `This tenant still has ${linkedStaff} linked Staff account(s). Remove or reassign them before off-boarding the tenant.`
352	                });
353	            }
354	        }
355	
356	        const targetId = staffMember.id;
357	        const targetName = staffMember.name;
