193	router.patch('/:id', verifyToken, requireRole('FM', 'Tenant'), async (req, res) => {
194	    try {
195	        const booking = await Booking.findByPk(req.params.id);
196	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
197	
198	        const isFM = req.user.role === 'FM';
199	        const isOwnerTenant = req.user.role === 'Tenant' && booking.tenantId === req.user.id;
200	        if (!isFM && !isOwnerTenant) {
201	            return res.status(403).json({ error: 'You can only edit your own bookings.' });
202	        }
203	        if (['Completed', 'Cancelled'].includes(booking.status)) {
204	            return res.status(409).json({ error: `Cannot edit a ${booking.status} booking.` });
205	        }
206	
207	        // Whitelist — ignore any other fields (status, tenantId, booking_ref…).
208	        const updates = {};
209	        for (const field of EDITABLE_FIELDS) {
210	            if (field in req.body) updates[field] = req.body[field];
211	        }
212	        if (Object.keys(updates).length === 0) {
213	            return res.status(400).json({ error: 'No editable fields supplied.' });
214	        }
215	
216	        if ('driver_phone' in updates && !/^[+\d][\d\s-]{6,}$/.test(String(updates.driver_phone))) {
217	            return res.status(400).json({ error: 'driver_phone is not a valid phone number.' });
218	        }
219	
220	        // Slot-conflict validation on the resulting time window/bay.
221	        const newStart = 'slot_start' in updates ? updates.slot_start : booking.slot_start;
222	        const newEnd = 'slot_end' in updates ? updates.slot_end : booking.slot_end;
223	        const newBay = 'loading_bay' in updates ? updates.loading_bay : booking.loading_bay;
224	        if (newStart && newEnd) {
225	            if (new Date(newEnd) <= new Date(newStart)) {
226	                return res.status(400).json({ error: 'slot_end must be after slot_start.' });
227	            }
228	            const clash = await Booking.findOne({
229	                where: {
230	                    id: { [Op.ne]: booking.id }, // ignore the booking being edited
231	                    loading_bay: newBay,
232	                    status: { [Op.ne]: 'Cancelled' },
233	                    slot_start: { [Op.lt]: new Date(newEnd) },
234	                    slot_end: { [Op.gt]: new Date(newStart) }
235	                }
236	            });
237	            if (clash) {
238	                return res.status(409).json({ error: `${newBay} is already booked for that time window.` });
239	            }
240	        }
241	
242	        await booking.update(updates);
243	        res.status(200).json({ message: 'Booking updated.', booking });
244	    } catch (err) {
245	        console.error('Booking edit error:', err);
246	        res.status(500).json({ error: 'Could not update booking.' });
247	    }
248	});
