273	// ---------------------------------------------------------------------------
274	// GATE SCAN — FM only: scan/verify a driver pass by booking_ref at the bay.
275	//   body: { action: 'entry' | 'exit', observedPlate?: string }
276	//   entry: Pending/Confirmed → Arrived (+ WhatsApp arrival)
277	//   exit:  Arrived/Confirmed → Completed (+ WhatsApp completed + next-in-line)
278	// Plate mismatch is flagged (warn) but does not block. WhatsApp is non-fatal.
279	// ---------------------------------------------------------------------------
280	router.patch('/:ref/gate-scan', verifyToken, requireRole('FM'), async (req, res) => {
281	    try {
282	        const { action, observedPlate } = req.body;
283	        if (!['entry', 'exit'].includes(action)) {
284	            return res.status(400).json({ error: "action must be 'entry' or 'exit'." });
285	        }
286	
287	        const booking = await Booking.findOne({ where: { booking_ref: req.params.ref } });
288	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
289	
290	        // Optional plate verification (warn-only — never blocks the scan).
291	        let plateMatched = null;
292	        if (observedPlate && String(observedPlate).trim()) {
293	            const norm = (s) => String(s || '').toUpperCase().replace(/\s+/g, '');
294	            plateMatched = norm(observedPlate) === norm(booking.license_plate);
295	        }
296	
297	        let whatsappStatus = null;
298	        let nextInLine = null;
299	
300	        if (action === 'entry') {
301	            if (booking.status === 'Cancelled' || booking.status === 'Completed') {
302	                return res.status(409).json({ error: `Cannot mark arrival: booking is ${booking.status}.`, booking, plateMatched });
303	            }
304	            await booking.update({ status: 'Arrived', arrived_at: new Date() });
305	            try {
306	                whatsappStatus = await whatsapp.sendBookingArrived(booking);
307	            } catch (waErr) {
308	                console.error('WhatsApp notify failed (non-fatal):', waErr.message);
309	            }
310	        } else { // exit
311	            if (booking.status === 'Cancelled') {
312	                return res.status(409).json({ error: 'Cannot mark exit: booking is Cancelled.', booking, plateMatched });
313	            }
314	            if (booking.status === 'Completed') {
315	                // Idempotent — already completed, do not re-notify / re-trigger next-in-line.
316	                return res.status(200).json({
317	                    message: 'Booking already completed.', booking, action,
318	                    plateMatched, whatsappStatus: null, nextInLine: null, alreadyCompleted: true
319	                });
320	            }
321	            await booking.update({ status: 'Completed', completed_at: new Date() });
322	            try {
323	                whatsappStatus = await whatsapp.sendBookingCompleted(booking);
324	                const next = await Booking.findOne({
325	                    where: { loading_bay: booking.loading_bay, status: { [Op.in]: ['Pending', 'Confirmed'] } },
326	                    order: [['slot_start', 'ASC'], ['createdAt', 'ASC']]
327	                });
328	                if (next) {
329	                    await whatsapp.sendNextInLine(next);
330	                    nextInLine = next.booking_ref;
331	                }
332	            } catch (waErr) {
333	                console.error('WhatsApp notify failed (non-fatal):', waErr.message);
334	            }
335	        }
336	
337	        return res.status(200).json({
338	            message: `Gate ${action} recorded.`, booking, action, plateMatched, whatsappStatus, nextInLine
339	        });
340	    } catch (err) {
341	        console.error('Gate scan error:', err);
342	        return res.status(500).json({ error: 'Could not process gate scan.' });
343	    }
344	});
