1	// Mock-safe WhatsApp Cloud API service for Smart Logistics.
2	//
3	// Reads ALL credentials from environment variables only — nothing is hardcoded.
4	//   WHATSAPP_ENABLED            must be exactly "true" to send for real (else mock mode)
5	//   WHATSAPP_API_URL            e.g. https://graph.facebook.com/v20.0
6	//   WHATSAPP_ACCESS_TOKEN       Meta access token (preferred)
7	//   WHATSAPP_API_KEY            fallback token if ACCESS_TOKEN is unset
8	//   WHATSAPP_PHONE_NUMBER_ID    Meta phone number id
9	//
10	// Never throws — always resolves to a result object so a booking flow can't crash on it.
11	
12	// Read config at call time so env changes (and tests) are picked up; token has a fallback.
13	function readConfig() {
14	  return {
15	    enabled: process.env.WHATSAPP_ENABLED === 'true',
16	    apiUrl: process.env.WHATSAPP_API_URL,
17	    token: process.env.WHATSAPP_ACCESS_TOKEN || process.env.WHATSAPP_API_KEY,
18	    phoneId: process.env.WHATSAPP_PHONE_NUMBER_ID,
19	  };
20	}
21	
22	// Backwards-compatible API-key mask (last 4 only).
23	function maskKey(key) {
24	  if (!key) return '(none)';
25	  return key.length <= 4 ? '****' : `****${key.slice(-4)}`;
26	}
27	
28	// Access-token mask — first 6 + last 4 only.
29	function maskToken(token) {
30	  if (!token) return '(none)';
31	  return token.length <= 10 ? '****' : `${token.slice(0, 6)}...${token.slice(-4)}`;
32	}
33	
34	// Phone mask — last 4 digits only.
35	function maskPhone(raw) {
36	  const digits = String(raw || '').replace(/\D/g, '');
37	  if (!digits) return '(none)';
38	  return digits.length <= 4 ? '****' : `****${digits.slice(-4)}`;
39	}
40	
41	// Normalize Singapore numbers: strip spaces/dashes/+, add 65 to bare 8-digit locals.
42	function normalizePhone(raw) {
43	  let p = String(raw || '').replace(/[\s-]/g, '');
44	  if (p.startsWith('+')) p = p.slice(1);
45	  p = p.replace(/\D/g, '');
46	  if (p.length === 8) p = `65${p}`;
47	  return p;
48	}
49	
50	function isConfigured() {
51	  const c = readConfig();
52	  return c.enabled && Boolean(c.apiUrl && c.token && c.phoneId);
53	}
54	
55	// HTTP helper: prefer global fetch (Node 18+); fall back to axios if unavailable.
56	async function httpPostJson(url, token, payload) {
57	  const headers = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
58	  if (typeof fetch === 'function') {
59	    const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(payload) });
60	    let data = {};
61	    try { data = await res.json(); } catch { /* non-JSON body */ }
62	    return { ok: res.ok, status: res.status, data };
63	  }
64	  const axios = require('axios');
65	  try {
66	    const r = await axios.post(url, payload, { headers, timeout: 10000 });
67	    return { ok: true, status: r.status, data: r.data };
68	  } catch (e) {
69	    return { ok: false, status: e.response?.status, data: e.response?.data };
70	  }
71	}
72	
73	// Core sender. Never throws — always resolves to a result object.
74	async function sendMessage(to, body) {
75	  const { enabled, apiUrl, token, phoneId } = readConfig();
76	
77	  // Mock mode: WHATSAPP_ENABLED is not exactly "true".
78	  if (!enabled) {
79	    console.log(`[WhatsApp] Simulated send (WHATSAPP_ENABLED is not "true"). to=${maskPhone(to)} body="${body}"`);
80	    return { success: true, simulated: true, message: 'WhatsApp disabled — message simulated.' };
81	  }
82	
83	  // Enabled but misconfigured → safe failure (do not call the API, do not crash).
84	  if (!apiUrl || !token || !phoneId) {
85	    console.error('[WhatsApp] Enabled but missing config (API_URL / token / PHONE_NUMBER_ID) — cannot send.');
86	    return { success: false, simulated: false, error: 'WhatsApp is enabled but credentials are incomplete.' };
87	  }
88	
89	  const normalized = normalizePhone(to);
90	  const url = `${apiUrl.replace(/\/$/, '')}/${phoneId}/messages`;
91	  const payload = {
92	    messaging_product: 'whatsapp',
93	    to: normalized,
94	    type: 'text',
95	    text: { preview_url: false, body },
96	  };
97	
98	  try {
99	    const result = await httpPostJson(url, token, payload);
100	    if (!result.ok) {
101	      const metaMsg = result.data?.error?.message || `HTTP ${result.status || 'error'}`;
102	      console.error(`[WhatsApp] Send failed to ${maskPhone(normalized)} (token ${maskToken(token)}): ${metaMsg}`);
103	      return { success: false, simulated: false, error: metaMsg };
104	    }
105	    console.log(`[WhatsApp] Sent to ${maskPhone(normalized)} (token ${maskToken(token)})`);
106	    return { success: true, simulated: false, message: 'WhatsApp message sent.' };
107	  } catch (err) {
108	    console.error(`[WhatsApp] Send error to ${maskPhone(normalized)} (token ${maskToken(token)}): ${err.message}`);
109	    return { success: false, simulated: false, error: err.message };
110	  }
111	}
