113	function formatSlot(booking) {
114	  if (!booking.slot_start) return 'your scheduled time';
115	  try {
116	    return new Date(booking.slot_start).toLocaleString('en-SG', { dateStyle: 'medium', timeStyle: 'short' });
117	  } catch {
118	    return String(booking.slot_start);
119	  }
120	}
121	
122	function formatSlotRange(booking) {
123	  const start = formatSlot(booking);
124	  if (!booking.slot_end) return start;
125	  try {
126	    const end = new Date(booking.slot_end).toLocaleString('en-SG', { timeStyle: 'short' });
127	    return `${start} – ${end}`;
128	  } catch {
129	    return start;
130	  }
131	}
