133	// Driver-pass deep link (read base URL from env; falls back for local demo).
134	function driverPassLink(booking) {
135	  if (!booking.booking_ref) return '';
136	  const base = process.env.FRONTEND_URL || process.env.CLIENT_URL || 'http://localhost:5173';
137	  return `${base.replace(/\/$/, '')}/driver-pass/${booking.booking_ref}`;
138	}
