142	// Booking created — full details + driver pass link.
143	function sendBookingCreated(booking) {
144	  const link = driverPassLink(booking);
145	  const lines = [
146	    'FlowGuard — Harrison Food Factory',
147	    `Booking ${booking.booking_ref} received.`,
148	    `Company: ${booking.transport_company} · Plate: ${booking.license_plate}`,
149	    `Bay: ${booking.loading_bay} · Slot: ${formatSlotRange(booking)}`,
150	    link ? `Driver pass: ${link}` : null,
151	    'Please wait for confirmation before arriving.',
152	  ].filter(Boolean);
153	  return sendMessage(booking.driver_phone, lines.join('\n'));
