1	// Server-owned security audit logging for facial-recognition outcomes.
2	// Stores audit metadata only — never snapshots or biometric template data.
3	const { randomUUID } = require('crypto');
4	const { SecurityLog } = require('../models');
5	
6	// Repeated events at ~1 scan/sec would flood the table: one log per
7	// (event, identity, location) per cooldown window.
8	const LOG_COOLDOWN_MS = 30 * 1000;
9	const recentLogKeys = new Map(); // key -> last logged epoch ms
10	
11	const shouldWriteLog = (key, now = Date.now()) => {
12	  const last = recentLogKeys.get(key) || 0;
13	  if (now - last < LOG_COOLDOWN_MS) return false;
14	  recentLogKeys.set(key, now);
15	  // Opportunistic cleanup so the map never grows unbounded.
16	  if (recentLogKeys.size > 500) {
17	    for (const [k, t] of recentLogKeys) {
18	      if (now - t > LOG_COOLDOWN_MS) recentLogKeys.delete(k);
19	    }
20	  }
21	  return true;
22	};
23	
24	// Test hook — clears the dedup window.
25	const resetLogCooldowns = () => recentLogKeys.clear();
26	
27	// Audit information only — never the snapshot or protected biometric template.
28	const createSecurityLog = async ({ type, desc, severity, icon, personnelName, matchedUserId, confidence, cameraLocation }) => {
29	  try {
30	    await SecurityLog.create({
31	      id: randomUUID(),
32	      time: new Date().toLocaleTimeString('en-SG', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true }),
33	      type,
34	      desc,
35	      severity,
36	      icon,
37	      personnelName,
38	      matchedUserId: matchedUserId ?? null,
39	      confidence: confidence ?? null,
40	      cameraLocation: cameraLocation || 'Main Gate',
41	      reviewStatus: severity === 'safe' ? 'Resolved' : 'Pending Review'
42	    });
43	    return true;
44	  } catch (err) {
45	    // Logging must never break the recognition/attendance response.
46	    console.error('Security log write failed:', err.message);
47	    return false;
48	  }
49	};
50	
51	module.exports = { shouldWriteLog, createSecurityLog, resetLogCooldowns, LOG_COOLDOWN_MS };
