1	const express = require('express');
2	const router = express.Router();
3	const { randomUUID } = require('crypto');
4	
5	// Destructure BOTH sequelize (for raw queries) and SecurityLog from the auto-loader
6	const { sequelize, SecurityLog } = require('../models');
7	const { verifyToken } = require('../middlewares/auth');
8	
9	// 🔒 Every security-log route requires a valid JWT. These logs contain personnel
10	// identities and intrusion data, so they must not be publicly readable/writable.
11	router.use(verifyToken);
12	
13	const ALLOWED_REVIEW_STATUSES = ['Pending Review', 'False Positive', 'Escalated', 'Resolved'];
14	
15	// 1. POST Route: Catch the log from React and save it to PostgreSQL
16	//    AUTOMATIC TASK: AI recognition (V-Patrol) posts Access Granted / Intrusion events here.
17	router.post('/logs', async (req, res) => {
18	  try {
19	    const { time, type, desc, severity, icon, personnelName } = req.body;
20	
21	    // Safe access events are auto-resolved; anything else lands in the FM review queue.
22	    const reviewStatus = severity === 'safe' ? 'Resolved' : 'Pending Review';
23	
24	    const newLog = await SecurityLog.create({
25	      id: randomUUID(),   // server-generated UUID — no more duplicate key collisions
26	      time,
27	      type,
28	      desc,
29	      severity,
30	      icon,
31	      personnelName,
32	      reviewStatus
33	    });
34	
35	    res.status(201).json({ message: "Log secured in database", log: newLog });
36	  } catch (error) {
37	    console.error("Failed to save security log:", error);
38	    res.status(500).json({ error: "Internal server error while saving log." });
39	  }
40	});
41	
42	// 2. GET Route: Fetch logs for a specific person by Name
43	router.get('/logs/personnel/:name', async (req, res) => {
44	  try {
45	    const logs = await SecurityLog.findAll({
46	      where: { personnelName: req.params.name },
47	      order: [['createdAt', 'DESC']]
48	    });
49	
50	    res.status(200).json(logs);
51	  } catch (error) {
52	    console.error("Failed to fetch personnel logs:", error);
53	    res.status(500).json({ error: "Could not retrieve personnel timeline." });
54	  }
55	});
56	
57	// 3. GET Route: Fetch logs by User ID instead of name (For UserLogs.jsx)
58	router.get('/logs/user/:id', async (req, res) => {
59	  try {
60	    // Look up the target user (name for log matching + managerId/role for ownership).
61	    const users = await sequelize.query(
62	      'SELECT id, name, "managerId", role FROM users WHERE id = ?',
63	      {
64	        replacements: [req.params.id],
65	        type: sequelize.QueryTypes.SELECT
66	      }
67	    );
68	
69	    if (!users || users.length === 0) {
70	      return res.status(404).json({ error: "Personnel member not found." });
71	    }
72	
73	    const target = users[0];
74	
75	    // Ownership: FM sees anyone; a Tenant may only view logs for their own staff.
76	    const isFM = req.user.role === 'FM';
77	    const isOwnerTenant = req.user.role === 'Tenant' && String(target.managerId) === String(req.user.id);
78	    if (!isFM && !isOwnerTenant) {
79	      return res.status(403).json({ error: "You can only view logs for your own staff." });
80	    }
81	
82	    const userName = target.name;
83	
84	    const logs = await SecurityLog.findAll({
85	      where: { personnelName: userName },
86	      order: [['createdAt', 'DESC']]
87	    });
88	
89	    res.status(200).json({
90	      personnelName: userName,
91	      logs: logs
92	    });
93	  } catch (error) {
94	    console.error("Failed to fetch personnel logs by ID:", error);
95	    res.status(500).json({ error: "Could not retrieve activity logs." });
96	  }
97	});
98	
99	// 4. GET Route: Fetch logs for the dashboard / review queue.
100	//    Supports optional filtering: ?status=Pending Review and ?limit=100
101	router.get('/logs', async (req, res) => {
102	  try {
103	    const { status, limit } = req.query;
104	
105	    const where = {};
106	    if (status) {
107	      if (!ALLOWED_REVIEW_STATUSES.includes(status)) {
108	        return res.status(400).json({ error: "Invalid review status filter." });
109	      }
110	      where.reviewStatus = status;
111	    }
112	
113	    const logs = await SecurityLog.findAll({
114	      where,
115	      order: [['createdAt', 'DESC']],
116	      limit: Math.min(parseInt(limit, 10) || 15, 200)
117	    });
118	
119	    res.status(200).json(logs);
120	  } catch (error) {
121	    console.error("Failed to fetch logs:", error);
122	    res.status(500).json({ error: "Could not retrieve security timeline." });
123	  }
124	});
125	
126	// 5. PATCH Route: MANUAL TASK — FM reviews a suspicious log and updates its status/notes.
127	//    FM-only. status ∈ {Pending Review, False Positive, Escalated, Resolved}
128	router.patch('/logs/:id/review', async (req, res) => {
129	  try {
130	    if (req.user.role !== 'FM') {
131	      return res.status(403).json({ error: "Only Facilities Managers can review security logs." });
132	    }
133	
134	    const { reviewStatus, reviewNotes } = req.body;
135	
136	    if (!reviewStatus || !ALLOWED_REVIEW_STATUSES.includes(reviewStatus)) {
137	      return res.status(400).json({
138	        error: `reviewStatus is required and must be one of: ${ALLOWED_REVIEW_STATUSES.join(', ')}.`
139	      });
140	    }
141	
142	    const log = await SecurityLog.findByPk(req.params.id);
143	    if (!log) {
144	      return res.status(404).json({ error: "Security log not found." });
145	    }
146	
147	    await log.update({
148	      reviewStatus,
149	      reviewNotes: reviewNotes ?? log.reviewNotes,
150	      reviewedBy: req.user.email || `FM #${req.user.id}`,
151	      reviewedAt: new Date()
152	    });
153	
154	    res.status(200).json({ message: "Review updated.", log });
155	  } catch (error) {
156	    console.error("Failed to update review:", error);
157	    res.status(500).json({ error: "Could not update the security log review." });
158	  }
159	});
160	
161	module.exports = router;
